# Try: Process bottom-up so pixels can fall into cells above them
def falling_sand_bottomup(grid):
    new_grid = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # Process bottom to top
    for r in range(rows - 1, -1, -1):
        for c in range(cols):
            if grid[r][c] != 9:  # Foreground here
                if new_grid[r+1][c] == 9 and r + 1 < rows:  # Below is empty
                    new_grid[r+1][c] = grid[r][c]
                    new_grid[r][c] = 9

    return new_grid

